import {mkdir, readFile, writeFile} from 'node:fs/promises';
import {dirname, resolve} from 'node:path';
import {fileURLToPath} from 'node:url';
import {format, resolveConfig} from 'prettier';

const root = fileURLToPath(new URL('../', import.meta.url));
const contract = JSON.parse(
  await readFile(resolve(root, 'packages/mobile-runtime/protocol.json'), 'utf8'),
);
const banner =
  '// Generated by scripts/mobile-protocol-generate.mjs. Edit protocol.json, then regenerate.\n';
const sessionFixture = await readFile(
  resolve(root, 'packages/mobile-runtime/test/fixtures/native-session.json'),
  'utf8',
);
const sequenceFixture = await readFile(
  resolve(root, 'packages/mobile-runtime/test/fixtures/session-sequences.json'),
  'utf8',
);
const outputs = {
  'platforms/ios/Tests/TileflowTests/Fixtures/session-sequences.json': sequenceFixture,
  'platforms/android/tileflow/src/test/resources/session-sequences.json': sequenceFixture,
  'packages/react-native/test/fixtures/native-session-sequences.json': sequenceFixture,
  'packages/mobile-runtime/src/contract.ts': await format(
    `${banner}export const protocol = ${JSON.stringify(contract, null, 2)} as const;\n`,
    {
      ...(await resolveConfig(resolve(root, 'packages/mobile-runtime/src/contract.ts'))),
      parser: 'typescript',
    },
  ),
  'platforms/ios/Tests/TileflowTests/Fixtures/native-session.json': sessionFixture,
  'platforms/android/tileflow/src/test/resources/native-session.json': sessionFixture,
  'platforms/ios/Sources/Tileflow/Bridge/ProtocolContract.swift': `${banner}
enum ProtocolContract {
    static let version = ${contract.version}
    static let maximumMessageBytes = ${contract.maximumMessageBytes}
    static let maximumPendingRequests = ${contract.maximumPendingRequests}
    static let requestTimeoutMilliseconds = ${contract.requestTimeoutMs}
    enum Method: String {
${contract.methods.map((name) => `        case ${name}`).join('\n')}
    }
}
`,
  'platforms/android/tileflow/src/main/java/dev/tileflow/sdk/bridge/ProtocolContract.kt': `${banner}
package dev.tileflow.sdk.bridge

internal object ProtocolContract {
    const val VERSION = ${contract.version}
    const val MAXIMUM_MESSAGE_BYTES = ${contract.maximumMessageBytes}
    const val MAXIMUM_PENDING_REQUESTS = ${contract.maximumPendingRequests}
    const val REQUEST_TIMEOUT_MILLIS = ${contract.requestTimeoutMs}L
    enum class Method(val wireName: String) {
${contract.methods.map((name) => `        ${name.replaceAll(/([A-Z])/gu, '_$1').toUpperCase()}("${name}"),`).join('\n')}
    }
}
`,
};
for (const [path, content] of Object.entries(outputs)) {
  if (process.argv.includes('--check')) {
    if ((await readFile(resolve(root, path), 'utf8')) !== content)
      throw new Error(`Regenerate ${path}.`);
  } else {
    await mkdir(dirname(resolve(root, path)), {recursive: true});
    await writeFile(resolve(root, path), content);
  }
}
